-- 补完 baseParamsJsonData json 数据:
-- 因为 json 文件格式在不断被修改, 但有些旧 json 文件里并未写入新变量, 故在此函数内手动补完;
function IdolLive3D_BaseParamsJsonData:CompleteBaseParamsJsonData() 
    ---@type IdolLive3D_States
    local IdolLive3D_States = import('Game.IdolLive3D.IdolLive3D_States')
    ---

    assert( isTable(self.data.idleSwitch) )

    ------------------------------------
    local idle_100 = self.data.idleInteractiveState_100
    local idle_200 = self.data.idleInteractiveState_200

    assert( IdolLive3D_BaseParamsJsonData._InitCameraSpatialParams_IsNotSet((idle_100.initCameraSpatialParams) == false ) )
    assert( IdolLive3D_BaseParamsJsonData._InitCameraSpatialParams_IsNotSet((idle_200.initCameraSpatialParams) == false ) )
    assert( isNotNull(idle_100.freeTrackCenterPos) )
    assert( isNotNull(idle_200.freeTrackCenterPos) )

    ------------------------------------ 
    if isNull(idle_100.customLightDir) then 
        idle_100.customLightDir = Vector3.zero
    end 
    if isNull(idle_200.customLightDir) then 
        idle_200.customLightDir = Vector3.zero
    end 
    idle_100.customLightDir = Vector3( idle_100.customLightDir.x, idle_100.customLightDir.y, idle_100.customLightDir.z )
    idle_200.customLightDir = Vector3( idle_200.customLightDir.x, idle_200.customLightDir.y, idle_200.customLightDir.z )


    self:_PrepareSoundList( idle_100.sounds )
    self:_PrepareSoundList( idle_200.sounds )
    ---
    if isNull(idle_100.videoSubtitle) then 
        idle_100.videoSubtitle = IdolLive3D_BaseParamsJsonData._GetFullVideoSubtitle()
    end 
    if isNull(idle_200.videoSubtitle) then 
        idle_200.videoSubtitle = IdolLive3D_BaseParamsJsonData._GetFullVideoSubtitle()
    end 
    --- idle_100 / idle_200 的 playTimes, maxPlayTimes 在下方被统一写入了
    
    ------------------------------------ 
    assert( IdolLive3D_BaseParamsJsonData._IdolLive3D_LookatParams_IsNotSet(idle_100.idolLive3D_LookatParams) == false )
    assert( IdolLive3D_BaseParamsJsonData._IdolLive3D_LookatParams_IsNotSet(idle_200.idolLive3D_LookatParams) == false )

    ------------------------------------ 
    assert( IdolLive3D_BaseParamsJsonData._FreeCameraSpatialRange_IsNotSet(idle_100.LookCameraSpatialRange) == false )
    assert( IdolLive3D_BaseParamsJsonData._FreeCameraSpatialRange_IsNotSet(idle_200.LookCameraSpatialRange) == false )

    ------------------------------------ 
    assert( isNotNull(idle_100.freeCameraActiveSpatialRange) )
    assert( isNotNull(idle_200.freeCameraActiveSpatialRange) )

    --- 预制一些数据:
    IdolLive3D_BaseParamsJsonData._Prepare_FreeCameraActiveSpatialRange( idle_100.freeCameraActiveSpatialRange )
    IdolLive3D_BaseParamsJsonData._Prepare_FreeCameraActiveSpatialRange( idle_200.freeCameraActiveSpatialRange )

    ---------------- oths --------------------
    if isNull(self.data.oths) then 
        self.data.oths = {}
    end 


    ---------------- oths.cameraParams --------------------
    if isNull(self.data.oths.cameraParams) then 
        self.data.oths.cameraParams = {
            nearPlane = 0.05,
            farPlane = 500,
        }
    end 
    if self.data.oths.cameraParams.nearPlane == 0 then 
        self.data.oths.cameraParams.nearPlane = 0.05
    end
    if self.data.oths.cameraParams.farPlane == 0 then 
        self.data.oths.cameraParams.farPlane = 500
    end

    ---------------- oths.resources --------------------
    if isNull(self.data.oths.resources) then 
        self.data.oths.resources = {}
    end 

    ---------------- oths.resources.fullScreenFXs --------------------
    if isNull(self.data.oths.resources.fullScreenFXs) then 
        self.data.oths.resources.fullScreenFXs = {}
    end 
    if IdolLive3D_Utils.IsEachKeyUnique(self.data.oths.resources.fullScreenFXs) == false then 
        printError("资源 fullScreenFXs 中发现重复的 key")
    end 

    for _,fx in pairs(self.data.oths.resources.fullScreenFXs) do 
        if isNull(fx.color) then 
            fx.color = Color.white
        end 
    end

    ---------------- oths.resources.prefabs --------------------
    if isNull(self.data.oths.resources.prefabs) then 
        self.data.oths.resources.prefabs = {}
    end 
    if IdolLive3D_Utils.IsEachKeyUnique(self.data.oths.resources.prefabs) == false then 
        printError("资源 prefabs 中发现重复的 key")
    end 

    ---------------- oths.resources.materials --------------------
    if isNull(self.data.oths.resources.materials) then 
        self.data.oths.resources.materials = {}
    end 
    if IdolLive3D_Utils.IsEachKeyUnique(self.data.oths.resources.materials) == false then 
        printError("资源 materials 中发现重复的 key")
    end 
    -- for _,mt in pairs(self.data.oths.resources.materials) do 
    -- end

    ---------------- oths.demo --------------------
    if isNull(self.data.oths.demo) then 
        self.data.oths.demo = { isDemo =  false }
    end 

    ---------------- oths.luaPath --------------------
    self.data.oths.skinLuaEnv = nil -- 本皮肤的定制脚本

    ------------------------------------ 
    --- 自由轨道相机 json 数据:
    -- idle_100, idle_200 里的 freeTrackJsonPath 是新版数据, 在旧的 json 文件里可能不存在;

    assert( string.isEmpty(idle_100.freeTrackJsonPath) == false )
    assert( string.isEmpty(idle_200.freeTrackJsonPath) == false )

    -- 读取 自由相机轨道 json 文件
    idle_100.freeTrackJson = IdolLive3D_Utils.LoadJsonSync( idle_100.freeTrackJsonPath ) -- 比如: "Presets/IdolLive3D/FreeTrack/test1.json"
    idle_200.freeTrackJson = IdolLive3D_Utils.LoadJsonSync( idle_200.freeTrackJsonPath ) -- 比如: "Presets/IdolLive3D/FreeTrack/test1.json"


    --- =======================================
    idle_100.idleType = IdleType.Type_100 -- 手动填上
    idle_200.idleType = IdleType.Type_200 -- 手动填上

    ---
    if isNull(idle_100.freeCameraMode) then 
        idle_100.freeCameraMode = IdolLive3D_States.FreeCameraMode.PosFree
    end 
    if isNull(idle_200.freeCameraMode) then 
        idle_200.freeCameraMode = IdolLive3D_States.FreeCameraMode.PosFree
    end 

    if idle_100.freeCameraMode == IdolLive3D_States.FreeCameraMode.PosLocked then 
        self:_HandlePosLockedCameraParams( idle_100.posLockedCameraParams )
    end
    if idle_200.freeCameraMode == IdolLive3D_States.FreeCameraMode.PosLocked then 
        self:_HandlePosLockedCameraParams( idle_200.posLockedCameraParams )
    end

    ---
    if isNull(idle_100.rolePos) then 
        idle_100.rolePos = Vector3.zero
    end 
    if isNull(idle_200.rolePos) then 
        idle_200.rolePos = Vector3.zero
    end 

    self.idleStates = {
        idle_100, 
        idle_200
    }

    self.shortNameHash_idles = {
        { hash = Animator.StringToHash( idle_100.name), iState = idle_100 },
        { hash = Animator.StringToHash( idle_200.name), iState = idle_200 },
    }


    --- ================== Simple 动作 =====================
    for _,iState in pairs(self.data.simpleInteractiveStates) do 

        assert( type(iState.isCloseLookAt) == "boolean" )
        assert( type(iState.fxPrefabPath) == "string" )
        assert( isTable(iState.videoSubtitle) )
        self:_PrepareSoundList( iState.sounds )
        iState.fxTF = nil -- add
    end


    --- ================== 音效 动作 =====================
    self.data.soundInteractiveStates = checkTable(self.data.soundInteractiveStates)
    for i=1, table.count(self.data.soundInteractiveStates) do 
        local iState = self.data.soundInteractiveStates[i]
        if isNull(iState.name) then 
            iState.name = "sound_" .. tostring(i)
        end 
        if isNull(iState.videoSubtitle) then 
            iState.videoSubtitle = IdolLive3D_BaseParamsJsonData._GetFullVideoSubtitle()
        end 
        self:_PrepareSoundList( iState.sounds )
    end


    --- ================== timelines =====================
    for _,iState in pairs(self.data.timelineInteractiveStates) do 
        if isNull(iState.videoSubtitle) then 
            iState.videoSubtitle = IdolLive3D_BaseParamsJsonData._GetFullVideoSubtitle()
        end 
        if type(iState.easeOutBlendTime) ~= "number" then 
            iState.easeOutBlendTime = 2
        end 
        if isNull(iState.isCloseLookAt) then 
            iState.isCloseLookAt = false
        end 
        self:_PrepareSoundList( iState.sounds )
    end 

    --- ================== super timelines =====================
    self.data.superTimelineInteractiveStates = checkTable(self.data.superTimelineInteractiveStates)
    for _,iState in pairs(self.data.superTimelineInteractiveStates) do 
        assert( string.isEmpty(iState.firstClipId) == false )

        if type(iState.easeOutBlendTime) ~= "number" then 
            iState.easeOutBlendTime = 2
        end 

        for __,clip in pairs(iState.clips) do 
            assert( string.isEmpty( clip.timelinePath) == false )

            if isNull(clip.isCloseLookAt) then 
                clip.isCloseLookAt = false
            end 
            
            for ___,nextClipInfo in pairs(clip.nextClipInfos) do
                assert( string.isEmpty( nextClipInfo.clipId) == false )
            end

            if clip.enterConditionType == IdolLive3D_States.TimelineNodeEnterConditionType.T_NoCondition then 
                assert( table.count(clip.nextClipInfos) <= 1 )
            else 
                assert( table.count(clip.nextClipInfos) > 0 )
            end 

            if type(clip.easeInBlendTime) ~= "number" then 
                clip.easeInBlendTime = 1
            end 
            clip.easeInBlendTime = Mathf.Max( clip.easeInBlendTime, 0.0 )

            --- sceneNodes: 用来开启关闭的
            if isNull(clip.sceneNodes) then
                clip.sceneNodes = {}
            end
            if isNull(clip.sceneNodes.nodes) then 
                clip.sceneNodes.nodes = {}
            end 
            self:_PrepareSoundList( clip.sounds )

            ---
            if isNull(clip.customParams) then 
                clip.customParams = {}
            end
            self:_PrepareCustomParams( clip.customParams )

            ---
            if isNull(clip.customFreeTrack) then 
                clip.customFreeTrack = 
                {
                    -- 别的字段暂时略;
                    isUse = false,
                } 
            end
            if clip.customFreeTrack.isUse == true then 
                IdolLive3D_BaseParamsJsonData._Prepare_FreeCameraActiveSpatialRange( clip.customFreeTrack.freeCameraActiveSpatialRange ) -- !!! Must
            end

        end 
    end


    -- ===============================================


    self.idleSwitchData =   
    {
        idle_100 = {
            idleState = idle_100,
            LookCameraSpatialRange = idle_100.LookCameraSpatialRange,
            lookAtIKParams = idle_100.idolLive3D_LookatParams.lookAtIKParams,
        },
        idle_200 = {
            idleState = idle_200,
            LookCameraSpatialRange = idle_200.LookCameraSpatialRange,
            lookAtIKParams = idle_200.idolLive3D_LookatParams.lookAtIKParams,
        },

        -- 人造 iState, 为了塞进 queue 中记录信息...
        iState_from_100_To_200 = {
            stateType = IdolLive3D_States.InteractiveStateType.IdleSwitch,
            name = "from_100_To_200",
        },
        iState_from_200_To_100 = {
            stateType = IdolLive3D_States.InteractiveStateType.IdleSwitch,
            name = "from_200_To_100",
        },
        -- 没有 切 idle, 但是走了一遍流程, 用来播放 idle switch 全屏动画...
        iState_from_100_To_100 = {
            stateType = IdolLive3D_States.InteractiveStateType.IdleSwitch,
            name = "from_100_To_100",
        },
        iState_from_200_To_200 = {
            stateType = IdolLive3D_States.InteractiveStateType.IdleSwitch,
            name = "from_200_To_200",
        },
    }

    ---
    self.InteractiveStates = {} -- 包含: idle100/200, Simples, timelines, superTimelines
    table.insert( self.InteractiveStates, idle_100 )
    table.insert( self.InteractiveStates, idle_200 )

    for _,iState in pairs(self.data.simpleInteractiveStates) do 
        table.insert( self.InteractiveStates, iState )
    end
    for _,iState in pairs(self.data.timelineInteractiveStates) do 
        table.insert( self.InteractiveStates, iState )
    end
    for _,iState in pairs(self.data.superTimelineInteractiveStates) do 
        table.insert( self.InteractiveStates, iState )
    end

    ---
    for k,iState in pairs(self.InteractiveStates) do    
        iState.playTimes = 0 -- 本次进入场景后, 本动作的播放次数; 
        if type(iState.maxPlayTimes) ~= "number" then 
            iState.maxPlayTimes = -1
        end
    end

    --- 反解表: 具体name 可在 c# IdolLive3D_Utils.InteractStatesMap 中查找;
    self.name_to_InteractiveStates = {}
    for k,iState in pairs(self.InteractiveStates) do    
        self.name_to_InteractiveStates[iState.name] = iState
    end
    for k,iState in pairs(self.data.soundInteractiveStates) do    
        self.name_to_InteractiveStates[iState.name] = iState
    end
    self.name_to_InteractiveStates[self.idleSwitchData.iState_from_100_To_200.name] = self.idleSwitchData.iState_from_100_To_200
    self.name_to_InteractiveStates[self.idleSwitchData.iState_from_200_To_100.name] = self.idleSwitchData.iState_from_200_To_100
    self.name_to_InteractiveStates[self.idleSwitchData.iState_from_100_To_100.name] = self.idleSwitchData.iState_from_100_To_100
    self.name_to_InteractiveStates[self.idleSwitchData.iState_from_200_To_200.name] = self.idleSwitchData.iState_from_200_To_200

    ---
    self:_MakeSureAllTimelineStateIsUnique()
end



--- baseJson 的一些延迟初始化工作:
---@param baseBGM_ table  @ {sheet="",cue=""}
function IdolLive3D_BaseParamsJsonData:InitAfterSceneLoaded( baseBGM_ ) 

    -- 需要等 场景prefab 都加载进 "_Builds_" 之后:
    local buildsRootTF = IdolLive3D_Utils.FindRootTransformInIdol3DScene("_Builds_")
    assert( isNotNull(buildsRootTF) )
    --- ================== super timelines =====================
    for _,iState in pairs(self.data.superTimelineInteractiveStates) do 
        for __,clip in pairs(iState.clips) do 

            for _,sceneNode in pairs(clip.sceneNodes.nodes) do 
                IdolLive3D_BaseParamsJsonData._FindSceneNodeGO( buildsRootTF, sceneNode )
            end 
        end
    end


    -- ============= 收集入场信息 ==============
    
    -- 找出最初的 idle state:
    self.defaultInitIdleState = nil -- 啥也找不到时的备份 idle state
    self:GetInitIdleState()

    --- 找出所有会在 入场时自动播放的 timelines:
    local autoRunTimelineStates = {}
    local InsertTimelines = function( iState_ )
        if iState_.fromState == self.defaultInitIdleState.idleType and IdolLive3D_Utils.IsFreeCameraSpatialRangeSupportAllRange( iState_.cameraSpatialRange ) 
            and iState_.compareMode == IdolLive3D_States.CameraSpatialRangeCompareMode.Include
            and iState_.interactiveType == IdolLive3D_States.InteractiveType.Spacial
        then 
            table.insert( autoRunTimelineStates, iState_ )
        end 
    end
    for _,iState in pairs(self.data.timelineInteractiveStates) do   
        InsertTimelines(iState)
    end
    for _,iState in pairs(self.data.superTimelineInteractiveStates) do     -- !!! 未来支持
        InsertTimelines(iState)
    end
    if table.count(autoRunTimelineStates) > 1 then 
        printError("发现 1个以上 启动后自动播放的 timeline 动作:")
        for k,iState in pairs(autoRunTimelineStates) do 
            printError("timeline: " .. tostring(iState.name) )
        end     
    end

    self.firstTimelineState = nil -- 入场时需要自动播放的 timeline
    if table.count(autoRunTimelineStates) == 1 then 
        self.firstTimelineState = autoRunTimelineStates[1]
    end 

    -- =================
    --- 确认 bgm
    assert( isNotNull(baseBGM_) )
    self.baseBGM = baseBGM_


    if isNotNull(self.firstTimelineState) then 

        
        -- todo ...


    end 


end


---------------------- public -------------------------------


function IdolLive3D_BaseParamsJsonData:GetInitIdleState()
    if isNull(self.defaultInitIdleState) then  -- 啥也找不到时的备份 idle state
        -- 初始化:
        local idle_100 = self:Get_Idle_100()
        local idle_200 = self:Get_Idle_200()
        local origin_idleState = idle_100
        if self:IsIdleSwitchByButton() or self:IsIdleSwitchSupportFromSuperTimeline() then
            origin_idleState = (self.data.idleSwitch.initIdleStateTypeInButtonMode == IdleType.Type_100) and idle_100 or idle_200
        end
        ---
        if self.data.idleSwitch.isNeedIdleSwitch and self.data.idleSwitch.idleSwitchMode == IdolLive3D_States.IdleSwitchMode.ByCameraSpacial then 
            self.defaultInitIdleState = origin_idleState
            --initIdleType = self.defaultInitIdleState.idleType
            print("-1-ByCameraSpacial: init idle state = " .. tostring(self.defaultInitIdleState.desc) )
        else 
            -- -1-: 不支持 idle switch: 
            -- -2-: 用按钮来 switch:
            local initIdleType = self.data.idleSwitch.initIdleStateTypeInButtonMode
            self.defaultInitIdleState = self:IdleType_To_IdleState(initIdleType, true)
            print("-2-ByButton: init idle state = " .. tostring(self.defaultInitIdleState.desc) )
        end
        assert( isNotNull(self.defaultInitIdleState) )
    end
    ---
    return self.defaultInitIdleState
end




function IdolLive3D_BaseParamsJsonData:FindCurrentIdleState( cameraSpatialParams_ )
    if isNull(cameraSpatialParams_) then 
        printError("参数 cameraSpatialParams_ 异常")
        return self:Get_Idle_100()
    end    
    for _,iState in pairs(self.idleStates) do 
        if IdolLive3D_Utils:IsCameraSpatialParamsInRange(iState.cameraSpatialRange, cameraSpatialParams_, iState.compareMode ) then 
            return iState
        end 
    end
    ---
    printError("koko - 没找到 当前 idle state")
    return self:Get_Idle_100()
end




function IdolLive3D_BaseParamsJsonData:Get_Idle_100() 
    return self.data.idleInteractiveState_100
end 

function IdolLive3D_BaseParamsJsonData:Get_Idle_200() 
    return self.data.idleInteractiveState_200
end 



function IdolLive3D_BaseParamsJsonData:Find_TimelineState( timelineName_ ) 
    for _,iState in pairs(self.data.timelineInteractiveStates) do 
        if iState.name == timelineName_ then 
            return iState
        end 
    end
    return nil
end


function IdolLive3D_BaseParamsJsonData:Find_SuperTimelineState( superTimelineName_ ) 
    for _,iState in pairs(self.data.superTimelineInteractiveStates) do 
        if iState.name == superTimelineName_ then 
            return iState
        end 
    end
    return nil
end


function IdolLive3D_BaseParamsJsonData:IsIdleSwitchByButton()
    return self.data.idleSwitch.isNeedIdleSwitch and self.data.idleSwitch.idleSwitchMode == IdolLive3D_States.IdleSwitchMode.ByButton
end

function IdolLive3D_BaseParamsJsonData:IsIdleSwitchSupportFromSuperTimeline()
    return self.data.idleSwitch.isSupportedFromSuperTimeline == true
end







function IdolLive3D_BaseParamsJsonData:IdleType_To_IdleState( idleType_, isNeedErrorCheck_ )
    if isNull(isNeedErrorCheck_) then
        isNeedErrorCheck_ = true
    end
    ---
    if idleType_ == IdleType.Type_100 then 
        return self.idleSwitchData.idle_100.idleState
    elseif idleType_ == IdleType.Type_200 then 
        return self.idleSwitchData.idle_200.idleState
    else 
        if isNeedErrorCheck_ == true then 
            printError("参数异常: " .. tostring(idleType_))
        end
        return nil
    end 
end 



---- 在 Simples, timelines, superTimelines 中找到 唯一的那一个 交互动作
---@return table or nil 
function IdolLive3D_BaseParamsJsonData:FindDemoInteractiveState()
    local demo = self.data.oths.demo
    if demo.isDemo ~= true then 
        printError("不是 demo, 不该调用本函数")
        return nil
    end 
    ---
    for k,iState in pairs(self.InteractiveStates) do    
        if iState.stateType ~= StateType.Idle and iState.name == demo.name then
            return iState
        end
    end
    ---
    printError("没找到, json demo name 配置有问题")
    return nil
end


---------------------- scene nodes (superTimeline clip 内) -------------------------------

---@param buildsRootTF_ UnityEngine.Transform 
---@param sceneNode_ table @ json node
function IdolLive3D_BaseParamsJsonData._FindSceneNodeGO( buildsRootTF_, sceneNode_ )
    assert( string.isEmpty(sceneNode_.path) == false )
    ---
    local nodeTF = buildsRootTF_:Find( sceneNode_.path )
    if isNotNull(nodeTF) then 
        sceneNode_.transform = nodeTF
    else 
        printError("没找到目标 scene node, path:" .. tostring(sceneNode_.path))
        sceneNode_.transform = nil
    end 
end



function IdolLive3D_BaseParamsJsonData.HandleSceneNodes( sceneNodes_, isStartPlayClip_ )
    assert( type(sceneNodes_.nodes) == "table" )
    local NodeShowType = IdolLive3D_States.NodeShowType

    for _,node in pairs(sceneNodes_.nodes) do
        if isNotNull(node.transform) then
            if isStartPlayClip_ == true then 
                KTool.SetActive( node.transform.gameObject, node.sceneNodeType==NodeShowType.T_Open or node.sceneNodeType==NodeShowType.T_Open_Hide )
            else 
                if node.sceneNodeType==NodeShowType.T_Hide_Open or node.sceneNodeType==NodeShowType.T_Open_Hide then 
                    KTool.SetActive( node.transform.gameObject, node.sceneNodeType==NodeShowType.T_Hide_Open  )
                end                 
            end
        else 
            printError("发现 scene node transform 为空")
        end
    end
end


--------------------------- private -------------------------------------

function IdolLive3D_BaseParamsJsonData._GetFullVideoSubtitle()
    return {
        id = "",
        waitTime = 0.0
    }
end


function IdolLive3D_BaseParamsJsonData._IdolLive3D_LookatParams_IsNotSet( params_ ) 
    return isNull(params_) or isNull(params_.lookAtIKParams)
end



function IdolLive3D_BaseParamsJsonData._FreeCameraSpatialRange_IsNotSet( params_ ) 
    return isNull(params_) or  isNull(params_.yaw) or isNull(params_.pitch) or isNull(params_.zoom)
end


function IdolLive3D_BaseParamsJsonData._GetNewFreeCameraSpatialRange()
    return {
        yaw = IdolLive3D_BaseParamsJsonData._GetNewDirRange(),
        pitch = IdolLive3D_BaseParamsJsonData._GetNewTRange(),
        zoom = IdolLive3D_BaseParamsJsonData._GetNewTRange(),
    }
end



function IdolLive3D_BaseParamsJsonData._Prepare_FreeCameraActiveSpatialRange( freeCameraActiveSpatialRange_ )
    local r = freeCameraActiveSpatialRange_
    --- yaw: 
    if r.yaw.range > 360 then 
        r.yaw.isUse = false
    end 
    if r.yaw.isUse == true then
        r.yaw.dir = Quaternion.Euler(0,r.yaw.dirDegree,0) * Vector3.forward
        local halfRange = r.yaw.range * 0.5
        r.yaw.leftDir  = Quaternion.Euler(0,-halfRange,0) * r.yaw.dir
        r.yaw.rightDir = Quaternion.Euler(0, halfRange,0) * r.yaw.dir
    end
    --- pitch:
    if r.pitch.from < 0.0001 and r.pitch.to > 0.99999 then 
        r.pitch.isUse = false
    end 
    --- zoom:
    if r.zoom.from < 0.0001 and r.zoom.to > 0.99999 then 
        r.zoom.isUse = false
    end 
end




function IdolLive3D_BaseParamsJsonData._IdolLive3D_LookatParams_CopyFrom( from_, to_ ) 
    assert( isTable(from_) )
