    assert( isTable(lap) )
    assert( type(lap.bodyWeight) == "number" )
    assert( type(lap.headWeight) == "number" )
    assert( type(lap.eyesWeight) == "number" )
    assert( type(lap.clampWeight) == "number" )
    assert( type(lap.clampWeightHead) == "number" )
    assert( type(lap.clampWeightEyes) == "number" )
    assert( type(lap.clampSmoothing) == "number" )
    to_.lookAtIKParams = {
        bodyWeight = lap.bodyWeight, 
        headWeight = lap.headWeight, 
        eyesWeight = lap.eyesWeight, 
        clampWeight = lap.clampWeight, 
        clampWeightHead = lap.clampWeightHead, 
        clampWeightEyes = lap.clampWeightEyes, 
        clampSmoothing = lap.clampSmoothing, 
    }
end 


function IdolLive3D_BaseParamsJsonData._DirRange_CopyFrom( from_, to_ ) 
