function IdolLive3D_BaseParamsJsonData._FreeCameraSpatialRange_CopyFrom( from_, to_ ) 
    assert( isTable(from_) )
    assert( isTable(from_.yaw) )
    assert( isTable(from_.pitch) )
    assert( isTable(from_.zoom) ) 
    to_.yaw = {}
    to_.pitch = {}
    to_.zoom = {}
    IdolLive3D_BaseParamsJsonData._DirRange_CopyFrom( from_.yaw, to_.yaw )
    IdolLive3D_BaseParamsJsonData._TRange_CopyFrom( from_.pitch, to_.pitch )
    IdolLive3D_BaseParamsJsonData._TRange_CopyFrom( from_.zoom, to_.zoom )
end



-- 等同于 c# 中的 FreeCameraSpatialParams.IsNotSet()
function IdolLive3D_BaseParamsJsonData._FreeCameraSpatialParams_IsNotSet( params_ ) 
    if isTable(params_) == false or type(params_.yaw) ~= "number" or type(params_.pitch) ~= "number" or type(params_.zoom) ~= "number" then 
        return true
    end 
    return Mathf.Approximately(params_.yaw,0) and Mathf.Approximately(params_.pitch,0) and Mathf.Approximately(params_.zoom,0)
end

-- 等同于 c# 中的 InitCameraSpatialParams.IsNotSet()
-- 目前 .from, .time 两个数据废弃不用了, 只使用 .to 这个值
function IdolLive3D_BaseParamsJsonData._InitCameraSpatialParams_IsNotSet( params_ )
    if isTable(params_) == false or isNull(params_.to) then 
        return true
    end 
    return IdolLive3D_BaseParamsJsonData._FreeCameraSpatialParams_IsNotSet(params_.to)
end


function IdolLive3D_BaseParamsJsonData._FreeCameraSpatialParams_CopyFrom( from_, to_ )
    assert( isTable(from_) )
    assert( type(from_.yaw) == "number" )
    assert( type(from_.pitch) == "number" )
    assert( type(from_.zoom) == "number" )
    assert( isTable(to_) )
    to_.yaw = from_.yaw
    to_.pitch = from_.pitch
    to_.zoom = from_.zoom
end 


function IdolLive3D_BaseParamsJsonData._InitCameraSpatialParams_CopyFrom( from_, to_ )
    assert( isTable(from_) )
    assert( type(from_.time) == "number" )
    assert( isTable(to_) )
    to_.from = {}
    to_.to = {}
    IdolLive3D_BaseParamsJsonData._FreeCameraSpatialParams_CopyFrom( from_.from, to_.from )
    IdolLive3D_BaseParamsJsonData._FreeCameraSpatialParams_CopyFrom( from_.to, to_.to )
    to_.time = from_.time
end



-- 把数据整理成可以直接用的格式
function IdolLive3D_BaseParamsJsonData:_HandlePosLockedCameraParams( posLockedCameraParams_ ) 
    local fov = posLockedCameraParams_.fov
    local vCamParams = posLockedCameraParams_.vCamParams

    posLockedCameraParams_.yaw = {
        min = posLockedCameraParams_.yawRange.min,
        max = posLockedCameraParams_.yawRange.max,
    }
    ---
    posLockedCameraParams_.pitch = {
        min = posLockedCameraParams_.pitchRange.min,
        max = posLockedCameraParams_.pitchRange.max,
    }
    ---
    posLockedCameraParams_.zoom = {
        init_t = vCamParams.range_t,
        minFov = Mathf.Clamp( fov - vCamParams.fovRange * vCamParams.range_t,     5, 70 ),
        maxFov = Mathf.Clamp( fov + vCamParams.fovRange * (1-vCamParams.range_t), 5, 70 ),
        minDistanceOffset =  - vCamParams.moveRange * vCamParams.range_t,
        maxDistanceOffset =    vCamParams.moveRange * (1-vCamParams.range_t),
    }
    --printError("zoom: " .. table.dump( posLockedCameraParams_.zoom ) )
end



function IdolLive3D_BaseParamsJsonData:_PrepareSoundList( sounds_ )
    if isTable(sounds_) then
        for _,e in pairs(sounds_) do 
            self:_PrepareSound( e )
        end 
    end
end
--- 装配 c# 中的 IdolLive3D.Sound 实例;
---@param sound_ table
function IdolLive3D_BaseParamsJsonData:_PrepareSound( sound_ )
    if isNull(sound_.soundPattern) then 
        sound_.soundPattern = IdolLive3D_States.SoundPattern.Default
    end 

    if isNull(sound_.gameNodeKey) then 
        sound_.gameNodeKey = ""
    end 
end




function IdolLive3D_BaseParamsJsonData:_PrepareCustomParams( customParams_ )
    if isNull(customParams_.singleParams) then 
        customParams_.singleParams = {}
    end
end


---@return string | nil
function IdolLive3D_BaseParamsJsonData.FindCustomSingleParams( customParams_, key_ )
    for _,e in pairs(customParams_.singleParams) do 
        if string.lower(e.key) == string.lower(key_) then 
            return e.value
        end 
    end
    return nil
end




-- timeline 和 superTimeline 不允许拥有重复的 state
function IdolLive3D_BaseParamsJsonData:_MakeSureAllTimelineStateIsUnique() 
    local ents = {}
    ---
    local DoCheck = function( iState_ )
        local key_ = tostring(iState_.state)
        if ents[key_] == nil then 
            ents[key_] = 1
        elseif ents[key_] == 1 then 
            printError("json 配置中出现了重复的 state: " .. tostring(iState_.name))
        end
    end
    ---
    for _,iState in pairs(self.data.timelineInteractiveStates) do 
        DoCheck( iState )
    end 
    for _,iState in pairs(self.data.superTimelineInteractiveStates) do 
        DoCheck( iState )
    end 
end




return IdolLive3D_BaseParamsJsonData